def find_minimum_viable_suction(target_reduction=1.0, tol=1.0):
    p_low = -250.0   # Upper bound suction (overkill)
    p_high = 0.0     # Lower bound suction (ineffective)

    while abs(p_high - p_low) > tol:
        p_mid = (p_low + p_high) / 2.0
        reduction = simulate_intervention(suction_p=p_mid)

        if reduction >= target_reduction:
            p_high = p_mid  # Can achieve target with less suction
        else:
            p_low = p_mid   # Insufficient disruption; need more suction

